namespace SuffixTree.Esa.Tests.Facade;

/// <summary>
/// Base of the derived copies of the existing ISuffixTree-level tests (<c>Facade/Ported</c>, generated by <c>port_facade_tests.py</c>): the copies call
/// <see cref="Tree(string)"/> where the originals call <c>SuffixTree.Build</c>, so the same assertions run for every backend of <see cref="SuffixTreeBackends.PortedFixtures"/>.
/// Trees that are <see cref="IDisposable"/> are disposed after the test (the originals of the Ukkonen suite never dispose, the persistent ones use <c>using</c>).
/// </summary>
public abstract class PortedBackendTestBase
{
    private readonly List<ISuffixTree> _created = [];

    /// <summary>Binds the fixture to a backend.</summary>
    /// <param name="backend">The backend under test.</param>
    protected PortedBackendTestBase(SuffixTreeBackend backend) => Backend = backend;

    /// <summary>The backend under test.</summary>
    protected SuffixTreeBackend Backend { get; }

    /// <summary>Builds the tree of a string.</summary>
    protected ISuffixTree Tree(string text) => Track(Backend.FromString(text));

    /// <summary>Builds the tree of a text source.</summary>
    protected ISuffixTree Tree(ITextSource text) => Track(Backend.FromSource(text));

    /// <summary>Builds the tree of a memory.</summary>
    protected ISuffixTree Tree(ReadOnlyMemory<char> text) => Tree(new string(text.Span));

    /// <summary>Builds the tree of a span.</summary>
    protected ISuffixTree Tree(ReadOnlySpan<char> text) => Tree(new string(text));

    /// <summary>The Ukkonen <c>TryBuild</c> semantics on top of the backend factory: null and a too long text give false, anything else the tree.</summary>
    protected bool TryBuild(ITextSource? value, out ISuffixTree? tree)
    {
        if (value is null || !SuffixTreeLimits.IsTextLengthSupported(value.Length))
        {
            tree = null;
            return false;
        }
        tree = Tree(value);
        return true;
    }

    /// <summary>The Ukkonen <c>TryBuild</c> semantics for a string.</summary>
    protected bool TryBuild(string? value, out ISuffixTree? tree)
    {
        if (value is null)
        {
            tree = null;
            return false;
        }
        tree = Tree(value);
        return true;
    }

    /// <summary>The k-common substrings of <paramref name="texts"/> (the static helper of the Ukkonen class, with this backend as the tree builder).</summary>
    protected IReadOnlyList<string> FindLongestCommonSubstrings(IReadOnlyList<string> texts, int? minSupport = null)
    {
        ArgumentNullException.ThrowIfNull(texts);
        return SuffixTreeAlgorithms.FindLongestCommonSubstrings(texts, minSupport ?? texts.Count, Backend.FromString);
    }

    /// <summary>The longest common substring lengths by support (the static helper of the Ukkonen class, with this backend as the tree builder).</summary>
    protected int[] LongestCommonSubstringLengthsBySupport(IReadOnlyList<string> texts)
        => SuffixTreeAlgorithms.LongestCommonSubstringLengthsBySupport(texts, Backend.FromString);

    /// <summary>Disposes the trees of the test.</summary>
    [TearDown]
    public void DisposeTrees()
    {
        foreach (ISuffixTree tree in _created)
            (tree as IDisposable)?.Dispose();
        _created.Clear();
    }

    private ISuffixTree Track(ISuffixTree tree)
    {
        _created.Add(tree);
        return tree;
    }
}
